+  const store = fresh();
+  const batch = (id, receivedOn, expires) => ({ id, itemId: 2, lot: `T-${id}`, qty: 1, receivedOn, expires, location: "fridge" });
+  store.data.batches = [
+    batch(101, "2026-10-01", null),
+    batch(102, "2026-10-20", "2026-11-05"),
+    batch(103, "2026-10-20", "2026-11-05"),
+    batch(104, "2026-10-10", "2026-11-05"),
+    batch(105, "2026-10-25", "2026-11-01"),
